/**
 * knowledge/codeNodes.ts — the code pack's vocabulary: its id, its badges, and the ONE
 * file-node / Extracted builder every code extractor shares (the per-file parser, the
 * repo-map converter and the analyzer converter), so a file is described the same way
 * whichever of them saw it.
 *
 * Pure: no I/O. Worker-safe.
 */

import { canonicalJson, COCHANGE_BADGE, srcRef, type Extracted, type KEdge, type KNode, type NodeRef } from '@seanhogg/builderforce-memory/knowledge';
import { areaOfPath } from '@seanhogg/builderforce-memory/working';
import { hashText } from '@seanhogg/builderforce-memory/ingest';
import { baseOf } from './systemPaths.js';

export const CODE_PACK_ID = 'code';

/** Badges the code pack puts on file nodes. */
export const CODE_BADGES = {
    /** The symbol extractor's language family (`js`, `python`, …). */
    language: 'language',
    /** Definitions in the file. */
    symbols: 'symbols',
    /** Exported definitions in the file. */
    exports: 'exports',
    /** knip: `'file'` when the whole file is unused. */
    unused: 'unused',
    /** knip: unused exports in the file. */
    unusedExports: 'unusedExports',
    /** knip: unused dependencies declared by the file (a package manifest). */
    unusedDependencies: 'unusedDependencies',
    /** knip: the names of the file's unused exports, sorted and comma-joined: one `unused-export` finding each (PRD 41 §C3). */
    unusedExportNames: 'unusedExportNames',
    /** knip: the names of the manifest's unused dependencies, sorted and comma-joined: one `unused-dependency` finding each. */
    unusedDependencyNames: 'unusedDependencyNames',
    /** Lines in the file (deterministic): the god-module finding's size measure. */
    lines: 'lines',
    /** Sum of cyclomatic complexity over the file's functions (deterministic). */
    complexity: 'complexity',
    /** The worst function's cyclomatic complexity (deterministic). */
    maxComplexity: 'maxComplexity',
    /** 0..1 line coverage from `coverage-final.json` / `lcov.info` under the root (runtime). */
    coverage: 'coverage',
    /** Commits touching the file in the last 90 days, from the host's `HistoryPort` (deterministic). */
    churn: 'churn',
    /** The file's co-change partners over the last year of history (memory's `encodeCoChange`, PRD 38 P4); absent with none. */
    coChange: COCHANGE_BADGE,
    /** First CODEOWNERS owner of the file (deterministic). */
    owner: 'owner',
    /** Comma-separated design-pattern ids (heuristic). */
    patterns: 'patterns',
    /** `METHOD path` route registrations joined by `;`, capped at 50 (deterministic). */
    routes: 'routes',
    /** The rule that placed the file's layer: `folder`, `name` or `imports`. */
    layerRule: 'layerRule',
    /** `1` on a package entry point a manifest names (`main` / `bin` / `exports`): layer resolution reads it, never the filesystem. */
    entry: 'entry',
    /** Comma-joined ids of the known external services the file imports (`postgres,llm`), from `externalServices.ts` (deterministic). */
    externals: 'externals',
    /** Comma-joined concurrency the file starts (`durable-object:ChatRoom,poller`), from `codeConcurrency.ts` (deterministic). */
    concurrency: 'concurrency',
} as const;

/**
 * Prefix of the `sourceHash` of ROOT-level output (repo graph, analyzers). Memory's
 * `buildGraph` keeps the first node it sees per ref, ordering Extracted by
 * (sourceRef, sourceHash): `~` sorts after every hex content hash, so the per-file
 * parser's node — the one carrying the file's real content hash — always wins, and the
 * root-level output only adds edges and badges.
 */
export const ROOT_OUTPUT_HASH_PREFIX = '~';


/** A code `file` node. `sourceHash` only from the per-file parser (see {@link ROOT_OUTPUT_HASH_PREFIX}). */
export function codeFileNode(
    rootId: string,
    path: string,
    opts: { sourceHash?: string; badges?: Record<string, number | string> } = {},
): KNode {
    const area = areaOfPath(path);
    const badges = opts.badges && Object.keys(opts.badges).length > 0 ? opts.badges : undefined;
    return {
        ref: srcRef(rootId, path), kind: 'file', label: baseOf(path) || path, pack: CODE_PACK_ID,
        ...(area ? { area: srcRef(rootId, area) } : {}),
        importance: 0, origin: 'extracted',
        ...(opts.sourceHash ? { sourceHash: opts.sourceHash } : {}),
        ...(badges ? { badges } : {}),
    };
}

/**
 * Root-level output for one file: its node plus outgoing edges, with a `sourceHash` that
 * is a pure function of the content (`~<tag>:<hash>`), so equal analyzer output gives an
 * equal graph digest whatever run produced it.
 */
export function rootLevelExtracted(tag: string, node: KNode, edges: KEdge[]): Extracted {
    const sourceRef: NodeRef = node.ref;
    const body = { nodes: [node], edges, keys: [] as Extracted['keys'] };
    return { sourceRef, sourceHash: `${ROOT_OUTPUT_HASH_PREFIX}${tag}:${hashText(canonicalJson(body))}`, ...body };
}


/**
 * The `sourceRef` of the ONE root-level Extracted that carries a review's signals (coverage,
 * churn, owner, entry). Not a `src:` ref, so it is no source of the root; its nodes are `src:`
 * file nodes that exist only where the per-file parser also made one.
 */
export const ROOT_SIGNALS_REF: NodeRef = 'ent:code:root-signals';
